/**
 * Fetch all events (Ticketmaster + other sources)
 */
export async function fetchAllEventsViaServer() {
  const data = await fetchFromAPI('/events');

  if (!data) {
    return { events: [], error: 'API unavailable' };
  }

  const allEvents = [];

  // Add Ticketmaster events
  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events.map(e => ({ ...e, source: 'ticketmaster' })));
  }

  // Add Kulturhuset events
  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset.map(e => ({ ...e, source: 'kulturhuset' })));
  }

  // Add Malmö Live events
  if (data.otherSources?.sources?.malmolive) {
    allEvents.push(...data.otherSources.sources.malmolive.map(e => ({ ...e, source: 'malmolive' })));
  }

  return {
    events: allEvents,
    count: allEvents.length,
    ticketmasterCount: data.ticketmaster?.count || 0,
  };
}

